#stage { --ground:#FFFFFF; --main:#8B5CF6; --second:#0B0B0A; --accent:#3B82F6; color:var(--second); font-family:var(--sans, system-ui, sans-serif) }
.ground { position:absolute; inset:0; background:var(--ground) }
.words { position:absolute; margin:0; display:flex; flex-direction:column; gap:24px } .words > * { margin:0 }
.line { font-family:var(--display, var(--sans, system-ui, sans-serif)); font-size:96px; line-height:1.04; font-weight:600; letter-spacing:-0.03em } .sub { font-size:34px; line-height:1.45; color:color-mix(in srgb, var(--second) 60%, var(--ground)) }
.box { position:absolute; margin:0 } .box { border:2px solid var(--second); box-sizing:border-box; font-size:24px; letter-spacing:.12em }
.box::after { content:attr(data-label); position:absolute; left:14px; bottom:10px }
.hw-tile { position:absolute; left:100px; width:1720px; height:832px; box-sizing:border-box; border-radius:40px; border:1.5px solid color-mix(in srgb, var(--second) 11%, var(--ground)); box-shadow:0 2px 4px rgba(0,0,0,.04), 0 -34px 64px -44px rgba(0,0,0,.28); overflow:hidden; transform-origin:50% 0 }
.hw-s0 { background:hsl(var(--how-sky)); --ink:hsl(var(--how-sky-ink)); --tone:hsl(var(--how-sky-accent)) }
.hw-s1 { background:hsl(var(--how-peach)); --ink:hsl(var(--how-peach-ink)); --tone:hsl(var(--how-peach-accent)) }
.hw-s2 { background:hsl(var(--how-lime)); --ink:hsl(var(--how-lime-ink)); --tone:hsl(var(--how-lime-accent)) }
.hw-tile { background-image:radial-gradient(100% 135% at 0% 0%, color-mix(in srgb, var(--tone) 20%, transparent), color-mix(in srgb, var(--tone) 10%, transparent) 40%, color-mix(in srgb, var(--tone) 3%, transparent) 70%, transparent 88%), radial-gradient(92% 125% at 100% 100%, color-mix(in srgb, var(--tone) 16%, transparent), color-mix(in srgb, var(--tone) 7%, transparent) 40%, color-mix(in srgb, var(--tone) 2%, transparent) 70%, transparent 86%) }
.hw-copy { position:absolute; left:72px; top:0; bottom:0; width:590px; display:flex; flex-direction:column; justify-content:center; gap:30px } .hw-copy > * { margin:0 }
.hw-step { font-family:var(--mono, ui-monospace, monospace); font-size:22px; font-weight:500; letter-spacing:.06em; color:var(--tone) }
.hw-title { font-size:54px; line-height:1.1; font-weight:600; letter-spacing:-0.025em } .hw-title span { display:block } .hw-lead { color:var(--ink) } .hw-accent { color:var(--tone) }
.hw-body { font-size:28px; line-height:1.5; color:color-mix(in srgb, var(--ink) 75%, transparent) }
.hw-note { font-size:24px; font-weight:500; color:var(--ink); display:flex; align-items:center; gap:14px } .hw-note::before { content:''; width:10px; height:10px; border-radius:50%; background:var(--tone) }
.hw-media { position:absolute; right:56px; top:54px; width:960px; height:720px; box-sizing:border-box; border-radius:28px; border:1.5px solid color-mix(in srgb, var(--second) 11%, var(--ground)); background:color-mix(in srgb, var(--ground) 72%, transparent); overflow:hidden }
.hw-canvas { position:absolute; left:0; top:0; width:640px; height:480px; transform:scale(1.5); transform-origin:0 0 }
.hw-shade { position:absolute; inset:0; background:var(--second); opacity:0; pointer-events:none }
